<script setup>
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '../../components/common/PageHeader.vue';import StatusView from '../../components/common/StatusView.vue';import {getProduct} from '../../api/catalog.js'
const route=useRoute(),item=ref(),loading=ref(true);onMounted(async()=>{try{item.value=(await getProduct(route.params.id)).data}finally{loading.value=false}})
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="产品详情" :breadcrumbs="['首页','产品中心','产品详情']"/><StatusView v-if="loading" type="loading"/><div v-else-if="item" class="detail-grid"><img class="detail-image" :src="item.image" :alt="item.name"><div class="detail-panel"><span class="eyebrow">{{item.category}} · {{item.style}}</span><h1>{{item.name}}</h1><p class="muted detail-copy">{{item.description}}</p><div class="detail-meta"><span class="muted">主要材质</span><strong>{{item.material}}</strong><span class="muted">功能特点</span><div><span v-for="f in item.features" :key="f" class="feature">{{f}}</span></div></div><div class="detail-actions"><el-button type="primary" size="large" @click="$router.push('/customize')">以此系列开始定制</el-button><el-button size="large" @click="$router.push('/cases')">查看相关案例</el-button></div></div></div><StatusView v-else type="error" title="未找到产品"/></div></div></template>
<style scoped>.detail-image{height:560px}.detail-copy{font-size:16px;line-height:1.9}.feature{display:inline-block;margin:0 14px 8px 0}.detail-actions{display:flex;gap:12px;margin-top:28px}@media(max-width:700px){.detail-image{height:320px}.detail-actions{align-items:stretch;flex-direction:column}}</style>
